// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 sendAmount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));

        sendAmount = bound(sendAmount, 0, 1 ether);

        Receiver r = new Receiver();

        vm.deal(address(this), sendAmount);

        c.sendMoney(address(r), sendAmount, "");

        vm.deal(attacker, 1 ether);

        bool ok;
        vm.prank(attacker);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Receiver {
    receive() external payable {}
}
